// ClearMark Brand Playbook (v3, September 19, 2026), shown only to logged-in team members.
// Imported by a server page, so it is never sent to visitors who are not logged in.
export const playbookHtml = "<header class=\"wrap crm-hero\">\n  <p class=\"who\">ClearMark brand playbook for Andrew Kreick and Tim Ferman, version 3, September 19, 2026</p>\n  <h1>Your single source of truth shouldn't be a person.</h1>\n  <p class=\"tag\">Make it visible.</p>\n  <p class=\"purpose\">Everything you need to say it the same way everywhere: the messaging framework, why each channel exists, copy you can paste, and the order to do it in.</p>\n</header>\n<nav class=\"crm-sections\" aria-label=\"Sections\">\n  <ul>\n    <li><a href=\"#framework\">Framework</a></li>\n    <li><a href=\"#channels\">Channels</a></li>\n    <li><a href=\"#content\">Content</a></li>\n    <li><a href=\"#timeline\">Timeline</a></li>\n  </ul>\n</nav>\n<main class=\"wrap\">\n<section class=\"part\" id=\"framework\" aria-labelledby=\"fw-h\">\n  <h2 id=\"fw-h\">Messaging framework</h2>\n  <p class=\"lede\">Read it top to bottom. Each level comes from the one above it, and the proof at the bottom holds everything up. Every box can be copied.</p>\n  <ol class=\"cascade\">\n    <li class=\"level l1\">\n      <p class=\"level-name\">The promise</p>\n      <p class=\"level-desc\">What every channel ultimately says.</p>\n      <div class=\"node parent block\">\n        <div class=\"block-head\"><h3>Headline and tagline</h3><button class=\"copy\" type=\"button\">Copy</button></div>\n        <div class=\"copytext\"><span class=\"big\">Your single source of truth shouldn't be a person.</span>\n<span class=\"big-tag\">Make it visible.</span></div>\n      </div>\n      <div class=\"node block\">\n        <div class=\"block-head\"><h3>Company promise vs. Agency Systems hook</h3><button class=\"copy\" type=\"button\">Copy</button></div>\n        <p class=\"copytext\">\"Making your workflows work\" is the promise behind every branch on the offer ladder below — Agency Systems, Content System, Publishing System, all of it. \"Your single source of truth shouldn't be a person / Make it visible\" is Agency Systems' own sharp, FATE-tested hook. Use the company line on your own bio and anything spanning branches; keep \"Make it visible\" as the headline on everything agency-facing, exactly as built out below.</p>\n      </div>\n      <div class=\"node block\">\n        <div class=\"block-head\"><h3>Brand promise</h3><button class=\"copy\" type=\"button\">Copy</button></div>\n        <p class=\"copytext\">Your agency keeps delivering when your best creative is out of the room, and your clients can see the work well enough to buy more of it.</p>\n      </div>\n      <div class=\"node block\">\n        <div class=\"block-head\"><h3>Sign-off</h3><button class=\"copy\" type=\"button\">Copy</button></div>\n        <p class=\"copytext\"><strong>ClearMark.</strong> Make it visible.</p>\n      </div>\n    </li>\n\n    <li class=\"level l2\">\n      <p class=\"level-name\">The foundation</p>\n      <p class=\"level-desc\">Who it's for, what we are, and why it works.</p>\n      <div class=\"node block\">\n        <div class=\"block-head\"><h3>Value proposition</h3><button class=\"copy\" type=\"button\">Copy</button></div>\n        <p class=\"copytext\">ClearMark builds artificial intelligence (AI) production systems your agency's team can see and run. They work because the system comes first, and a creative director with 26 years inside agencies builds it. For PayPal in 2024, putting 300+ creatives on one shared journey board led to a new email strategy that lifted click-through from 17% to 54%.</p>\n      </div>\n      <div class=\"node block\">\n        <div class=\"block-head\"><h3>Positioning statement</h3><button class=\"copy\" type=\"button\">Copy</button></div>\n        <p class=\"copytext\">ClearMark is an AI creative systems practice for owners and production leaders at agencies of 15 to 200 people, led by a creative director who has spent 26 years inside agencies. We build the production system first, a shared view of the work running in the tools you already use, then add AI and train your team to run it. AI consultants have often never run production, and tools leave the setup to you. We deliver a working prototype in three weeks and a live cycle to prove it.</p>\n      </div>\n      <div class=\"node block\">\n        <div class=\"block-head\"><h3>Target audience</h3><button class=\"copy\" type=\"button\">Copy</button></div>\n        <p class=\"copytext\">Owners, managing directors, and heads of production at agencies of 15 to 200 people, where one person knows where every job stands, or where clients have been promised AI and automation that isn't fully built yet. They trust practitioners over consultants and want proof in agency terms and a low-risk way to start.</p>\n        <p class=\"gap\">Secondary: publishers, through Brad Herman. Parked: enterprise AI governance, exit-ready owners, jewelry.</p>\n      </div>\n      <div class=\"node block\">\n        <div class=\"block-head\"><h3>The offer ladder</h3><button class=\"copy\" type=\"button\">Copy</button></div>\n        <p class=\"copytext\">One capability, four ways to buy it. From here down, this framework (the message, the selling points, the pillars) is written for the Agency Systems branch, the current push. The other three branches are real and already in the pipeline, but each needs its own positioning pass before it's pitch-ready.</p>\n        <ul class=\"children\">\n          <li class=\"block\"><div class=\"block-head\"><h4>Lead-Gen Offer — $37, one-time</h4><button class=\"copy\" type=\"button\">Copy</button></div><p class=\"copytext\">A working interview: a fast, low-cost proof-of-work build with a money-back guarantee, meant to upgrade into a Content System tier. Draft.</p></li>\n          <li class=\"block\"><div class=\"block-head\"><h4>Content System — $125 to $500 a month</h4><button class=\"copy\" type=\"button\">Copy</button></div><p class=\"copytext\">The productized content engine (Self-Serve, Standard, White Glove): a custom-branded AI content calendar and video scripts. Buyer is the social media manager or owner at a small business, not an agency. First pilot: K&amp;Co Family Jewelers, running through Tim. Draft.</p></li>\n          <li class=\"block\"><div class=\"block-head\"><h4>Agency Systems — $2,500 to $5,000 setup, $500 to $1,500 a month retainer</h4><button class=\"copy\" type=\"button\">Copy</button></div><p class=\"copytext\">The pilot business the rest of this playbook is built for. Buyer is the agency owner or production lead. Ready.</p></li>\n          <li class=\"block\"><div class=\"block-head\"><h4>Publishing System — $1,500 to $5,000, project-based</h4><button class=\"copy\" type=\"button\">Copy</button></div><p class=\"copytext\">Book Relaunch Calendar and Concept-to-Market Sprint, built on the Nori SURGE and La Palabra proof already in this playbook. Sellable directly to a publisher or author, not only as a Nori renewal add-on. Draft.</p></li>\n        </ul>\n        <p class=\"gap\">Source: 7EOS product database, September 2026. Agency Systems setup and retainer prices are estimates off typical budgets, not numbers quoted live — validate before quoting.</p>\n      </div>\n    </li>\n\n    <li class=\"level l3\">\n      <p class=\"level-name\">The message</p>\n      <p class=\"level-desc\">The elevator pitch that carries the promise.</p>\n      <div class=\"node block\">\n        <div class=\"block-head\"><h3>Primary message</h3><button class=\"copy\" type=\"button\">Copy</button></div>\n        <div class=\"copytext\"><strong>Your single source of truth shouldn't be a person.</strong>\nMake it visible.\n\nWhen every job runs through your best creative, the agency stalls when they do. We build AI production systems your team can run, and a shared view of the work that makes your next idea easier to sell. For PayPal, putting 300+ creatives on one board led to a new email strategy that lifted click-through from 17% to 54%.\n\nWe build one pilot at a time: a working prototype in three weeks, one live cycle to prove it, and then your team runs it. You'll hear from us twice a week while we build, and the live cycle ends with a measured result.</div>\n      </div>\n    </li>\n\n    <li class=\"level l4\">\n      <p class=\"level-name\">What sets us apart</p>\n      <p class=\"level-desc\">Three selling points, each with its own proof underneath.</p>\n      <div class=\"node block\">\n        <div class=\"block-head\"><h3>Selling point 1</h3><button class=\"copy\" type=\"button\">Copy</button></div>\n        <div class=\"copytext\"><span class=\"claim\">One board your client can see</span>\nAccount teams sell more ideas because agency and client review the whole journey in one view. For PayPal in 2024, 300+ creatives on one board, from acquisition to retention, revealed a new email strategy.</div>\n        <ul class=\"children\">\n          <li class=\"proofline\"><b>Proof:</b> 300+ creatives on one journey board. Email click-through from 17% to 54%. One shared agency and client view.</li>\n        </ul>\n      </div>\n      <div class=\"node block\">\n        <div class=\"block-head\"><h3>Selling point 2</h3><button class=\"copy\" type=\"button\">Copy</button></div>\n        <div class=\"copytext\"><span class=\"claim\">The AI you sold, actually built</span>\nAgencies deliver on their automation promises because we build the system before the client notices it's missing. For a client's retail advertising program, we rebuilt 500+ ads from Photoshop and After Effects into one live system in under three months.</div>\n        <ul class=\"children\">\n          <li class=\"proofline\"><b>Proof:</b> 500+ ads rebuilt in under three months. Prototype approved, then a full live month delivered. Changes approved in real time in one shared file.</li>\n        </ul>\n        <p class=\"gap\">Keep the client and agency unnamed. A before-and-after turnaround time would strengthen this.</p>\n      </div>\n      <div class=\"node block\">\n        <div class=\"block-head\"><h3>Selling point 3</h3><button class=\"copy\" type=\"button\">Copy</button></div>\n        <div class=\"copytext\"><span class=\"claim\">Two people, 480 assets, 49 hours</span>\nAgencies get volume without adding headcount because a custom design system handles the repeat work. For La Palabra's 30-day campaign, we shipped 240 posts, 240 reels, a 50-page PDF, and a 32-page print devotional.</div>\n        <ul class=\"children\">\n          <li class=\"proofline\"><b>Proof:</b> 480 posts and reels in 49 working hours. A design system of 120+ images. Delivered to 10,000+ followers.</li>\n        </ul>\n        <p class=\"gap\">Delivered by Andrew and Ilse Kreick. It stays true as ClearMark's past work, but confirm you can still deliver this volume without Ilse before leading with it.</p>\n      </div>\n    </li>\n\n    <li class=\"level l5\">\n      <p class=\"level-name\">The pillars</p>\n      <p class=\"level-desc\">Three themes every piece of content comes back to, with the proof points beneath each.</p>\n\n      <div class=\"node block\">\n        <div class=\"block-head\"><h3>Pillar 1</h3><button class=\"copy\" type=\"button\">Copy</button></div>\n        <p class=\"copytext claim\">Everyone sees the work, so ideas sell faster</p>\n        <ul class=\"children\">\n          <li class=\"block\"><div class=\"block-head\"><h4>Proof point</h4><button class=\"copy\" type=\"button\">Copy</button></div><p class=\"copytext\">For PayPal in 2024, we put 300+ creatives on one board covering the full journey from acquisition to retention.</p></li>\n          <li class=\"block\"><div class=\"block-head\"><h4>Proof point</h4><button class=\"copy\" type=\"button\">Copy</button></div><p class=\"copytext\">That view led to a new email strategy, and click-through rose from 17% to 54%.</p></li>\n          <li class=\"block\"><div class=\"block-head\"><h4>Proof point</h4><button class=\"copy\" type=\"button\">Copy</button></div><p class=\"copytext\">On a 500+ ad retail program, the account team and client watched and approved changes in real time, in one shared file.</p></li>\n        </ul>\n      </div>\n\n      <div class=\"node block\">\n        <div class=\"block-head\"><h3>Pillar 2</h3><button class=\"copy\" type=\"button\">Copy</button></div>\n        <p class=\"copytext claim\">Your agency runs on a system, not one person</p>\n        <ul class=\"children\">\n          <li class=\"block\"><div class=\"block-head\"><h4>Proof point</h4><button class=\"copy\" type=\"button\">Copy</button></div><p class=\"copytext\">At a Christian publishing house, replacing 300 tracked tasks with 63 visible outcomes cut launches from 360 days to 16 weeks, with all four beta titles on time.</p></li>\n          <li class=\"block\"><div class=\"block-head\"><h4>Proof point</h4><button class=\"copy\" type=\"button\">Copy</button></div><p class=\"copytext\">A team member with no prior experience on the tools was trained to run the production system in two days.</p></li>\n          <li class=\"block\"><div class=\"block-head\"><h4>Proof point</h4><button class=\"copy\" type=\"button\">Copy</button></div><p class=\"copytext\">Changes no longer wait for the one designer with the file, a specialist to reopen it, or someone to rebuild the client presentation deck.</p></li>\n        </ul>\n      </div>\n\n      <div class=\"node block\">\n        <div class=\"block-head\"><h3>Pillar 3</h3><button class=\"copy\" type=\"button\">Copy</button></div>\n        <p class=\"copytext claim\">AI production that delivers what you promised</p>\n        <ul class=\"children\">\n          <li class=\"block\"><div class=\"block-head\"><h4>Proof point</h4><button class=\"copy\" type=\"button\">Copy</button></div><p class=\"copytext\">500+ retail ads were rebuilt from Photoshop and After Effects into one live system in under three months, with a full live month delivered after approval.</p></li>\n          <li class=\"block\"><div class=\"block-head\"><h4>Proof point</h4><button class=\"copy\" type=\"button\">Copy</button></div><p class=\"copytext\">Two people produced 480 finished posts and reels for La Palabra in 49 working hours.</p></li>\n          <li class=\"block\"><div class=\"block-head\"><h4>Proof point</h4><button class=\"copy\" type=\"button\">Copy</button></div><p class=\"copytext\">A full 12-style typography system was built and applied through the Figma API in a single session, then documented for reuse.</p></li>\n        </ul>\n      </div>\n\n      <div class=\"node block\">\n        <div class=\"block-head\"><h3>Supporting quote</h3><button class=\"copy\" type=\"button\">Copy</button></div>\n        <p class=\"copytext\">\"Most people selling AI to agencies have never run production. Andrew has. He builds the system first, and that's why the AI actually works.\"\nJames Kinney, Chief AI Officer, INVNT</p>\n        <p class=\"gap\">Draft. Use only after James approves it, and disclose any referral compensation.</p>\n      </div>\n      <div class=\"node block\">\n        <div class=\"block-head\"><h3>How the team works</h3><button class=\"copy\" type=\"button\">Copy</button></div>\n        <p class=\"copytext\">Andrew builds the system. Tim Ferman, our Client Partner, is your day-to-day contact: he keeps you updated twice a week, answers your questions, and makes sure the live cycle ends with a measured result.</p>\n        <p class=\"gap\">A public promise. Missing an update once does more damage than never promising it.</p>\n      </div>\n    </li>\n  </ol>\n</section>\n\n<section class=\"part\" id=\"channels\" aria-labelledby=\"ch-h\">\n  <h2 id=\"ch-h\">Channel strategy</h2>\n  <p class=\"lede\">Why each channel exists, what it has to do, and how you'll know it's working. They're ordered by where your leads actually come from, so start at the top.</p>\n  <div class=\"rules\">\n    <h3>Before this playbook covers more than agencies</h3>\n    <ul>\n      <li>The Content System ladder ($37 entry, then $125 to $500 a month) is real and already in the pipeline — K&amp;Co Family Jewelers is the first pilot, running through Tim. It has its own buyer (a social media manager or small-business owner, not an agency) and its own channel plan (weekly LinkedIn system drops, landing pages, eventually ads), so it needs its own version of this playbook once it's built out. Everything below is still written for Agency Systems only.</li>\n      <li>Tim and Andrew haven't yet settled whether the Content System line runs inside ClearMark (Tim as Client Partner, as defined below) or as a separate Tim-and-Andrew joint venture. Don't write or send Content System copy under the ClearMark name until that's decided — it changes who's on the invoice.</li>\n      <li>The Publishing System line (Book Relaunch Calendar, Concept-to-Market Sprint) is proven and doesn't have this structure question — see the publishing page below.</li>\n    </ul>\n  </div>\n  <p class=\"subnote\">Status key: <span class=\"status s-ready\">Ready</span> <span class=\"status s-fill\">Add your details</span> <span class=\"status s-build\">Needs building</span> <span class=\"status s-later\">Later</span></p>\n\n  <div class=\"group\">\n    <h3>Referral and partners</h3>\n    <p>Where your leads come from. A warm intro already carries credibility, so these messages just need to be easy to repeat.</p>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">James: spoken pitch</span><span class=\"status s-ready\">Ready</span></div>\n      <dl><dt>Job</dt><dd>Give James something short enough to repeat word for word.</dd><dt>Why</dt><dd>He's well connected in the ad industry, and he needed a focused pitch before he could introduce you.</dd><dt>Measure</dt><dd>Introductions made per month</dd></dl>\n      <a class=\"jump\" href=\"#c-james-pitch\">See content</a></div>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">James: forwardable intro email</span><span class=\"status s-ready\">Ready</span></div>\n      <dl><dt>Job</dt><dd>Let James introduce you in writing in under a minute.</dd><dt>Why</dt><dd>Most introductions happen by email, and a paste-ready blurb removes the friction.</dd><dt>Measure</dt><dd>Intros that turn into calls</dd></dl>\n      <a class=\"jump\" href=\"#c-james-email\">See content</a></div>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">Omnitas referral brief</span><span class=\"status s-fill\">Add your details</span></div>\n      <dl><dt>Job</dt><dd>Show how ClearMark and Omnitas split the work.</dd><dt>Why</dt><dd>The partnership only starts working once you land a first agency client, and this brief makes that handoff clear.</dd><dt>Measure</dt><dd>Referrals in each direction</dd></dl>\n      <a class=\"jump\" href=\"#c-omnitas\">See content</a></div>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">Brad Herman: publishing intros</span><span class=\"status s-ready\">Ready</span></div>\n      <dl><dt>Job</dt><dd>Keep publishing introductions coming.</dd><dt>Why</dt><dd>Publishing is where your strongest timeline result comes from, and it funds the business.</dd><dt>Measure</dt><dd>Publishing intros and pilots</dd></dl>\n      <a class=\"jump\" href=\"#c-brad\">See content</a></div>\n  </div>\n\n  <div class=\"group\">\n    <h3>Sales conversation</h3>\n    <p>The biggest gap so far: what happens after an intro. Without these, warm leads go cold.</p>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">Follow-up email after an intro</span><span class=\"status s-fill\">Add your details</span></div>\n      <dl><dt>Job</dt><dd>Turn the intro into a booked call.</dd><dt>Why</dt><dd>Replying quickly and simply keeps the credibility James passed on.</dd><dt>Measure</dt><dd>Calls booked from intros</dd></dl>\n      <a class=\"jump\" href=\"#c-followup\">See content</a></div>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">Discovery call guide</span><span class=\"status s-ready\">Ready</span></div>\n      <dl><dt>Job</dt><dd>Qualify the agency and set up the pilot.</dd><dt>Why</dt><dd>This is the closed-door meeting, the one place you can tell the full retail story.</dd><dt>Measure</dt><dd>Calls that lead to proposals</dd></dl>\n      <a class=\"jump\" href=\"#c-discovery\">See content</a></div>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">Pilot proposal</span><span class=\"status s-fill\">Add your details</span></div>\n      <dl><dt>Job</dt><dd>Put the scope, timeline and price in writing.</dd><dt>Why</dt><dd>A fixed-scope proposal earns more per hour than a retainer. Price each one with the rate card rule.</dd><dt>Measure</dt><dd>Proposals signed</dd></dl>\n      <a class=\"jump\" href=\"#c-proposal\">See content</a></div>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">Case study one-pager</span><span class=\"status s-ready\">Ready</span></div>\n      <dl><dt>Job</dt><dd>Leave something behind that the champion can share internally.</dd><dt>Why</dt><dd>The creative leader usually recommends rather than decides, so they need something to show the owner.</dd><dt>Measure</dt><dd>Forwards and follow-up questions</dd></dl>\n      <a class=\"jump\" href=\"#c-onepager\">See content</a></div>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">Case study request after a pilot</span><span class=\"status s-later\">Later</span></div>\n      <dl><dt>Job</dt><dd>Turn the first pilot into agency proof.</dd><dt>Why</dt><dd>The Tribe gate only fully passes once an agency your buyer's size has chosen ClearMark.</dd><dt>Measure</dt><dd>A quote and a result secured</dd></dl>\n      <a class=\"jump\" href=\"#c-casestudy-request\">See content</a></div>\n  </div>\n\n  <div class=\"group\">\n    <h3>During the pilot</h3>\n    <p>Andrew goes heads-down while he builds. These keep the client confident that ClearMark is still there, like a \"Thinking\" indicator that never goes quiet. Tim owns all of them.</p>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">Twice-weekly client update</span><span class=\"status s-ready\">Ready</span></div>\n      <dl><dt>Job</dt><dd>Tell the client what's done, what's next, and ask one question.</dd><dt>Why</dt><dd>Silence during the build is when clients start to worry.</dd><dt>Measure</dt><dd>Updates sent on time</dd></dl>\n      <a class=\"jump\" href=\"#c-update\">See content</a></div>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">Weekly check-in</span><span class=\"status s-ready\">Ready</span></div>\n      <dl><dt>Job</dt><dd>Show progress on the shared board and settle open questions.</dd><dt>Why</dt><dd>Watching the system take shape builds trust before the live cycle.</dd><dt>Measure</dt><dd>Decisions made in the meeting</dd></dl>\n      <a class=\"jump\" href=\"#c-checkin\">See content</a></div>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">Question log and daily sync</span><span class=\"status s-ready\">Ready</span></div>\n      <dl><dt>Job</dt><dd>Collect client questions and get Andrew's answers once a day.</dd><dt>Why</dt><dd>Andrew stays focused, and every scope request gets logged instead of quietly growing the build.</dd><dt>Measure</dt><dd>Questions answered within a day</dd></dl>\n      <a class=\"jump\" href=\"#c-log\">See content</a></div>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">Live-cycle results summary</span><span class=\"status s-fill\">Add your details</span></div>\n      <dl><dt>Job</dt><dd>Close the pilot with a measured result.</dd><dt>Why</dt><dd>A number from the live cycle fills your biggest proof gap.</dd><dt>Measure</dt><dd>A result the client agrees with</dd></dl>\n      <a class=\"jump\" href=\"#c-results\">See content</a></div>\n  </div>\n\n  <div class=\"group\">\n    <h3>Owned channels</h3>\n    <p>Where James's intros land to check you out. These need to confirm \"this is for me\" within five seconds.</p>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">LinkedIn profile and banner</span><span class=\"status s-ready\">Ready</span></div>\n      <dl><dt>Job</dt><dd>Prove you're a credible practitioner who has worked with agencies like theirs.</dd><dt>Why</dt><dd>It's the first place anyone looks after an intro.</dd><dt>Measure</dt><dd>Profile views versus messages</dd></dl>\n      <a class=\"jump\" href=\"#c-linkedin-profile\">See content</a></div>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">Tim's LinkedIn profile</span><span class=\"status s-ready\">Ready</span></div>\n      <dl><dt>Job</dt><dd>Show Tim's ClearMark role to anyone who looks him up.</dd><dt>Why</dt><dd>Clients will check who their day-to-day contact is. His network isn't a lead source for agencies.</dd><dt>Measure</dt><dd>Role listed and consistent with the website</dd></dl>\n      <a class=\"jump\" href=\"#c-tim-linkedin\">See content</a></div>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">LinkedIn daily posts</span><span class=\"status s-ready\">Ready</span></div>\n      <dl><dt>Job</dt><dd>Show your expertise every weekday and test which opening lines land.</dd><dt>Why</dt><dd>95% of your network is agency people, and posts keep you visible without cold outreach.</dd><dt>Measure</dt><dd>Clicks on \"see more\" and comments from agency people</dd></dl>\n      <a class=\"jump\" href=\"#c-posts\">See content</a></div>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">Website home page</span><span class=\"status s-build\">Needs building</span></div>\n      <dl><dt>Job</dt><dd>Carry the full four-gate script and book pilot calls.</dd><dt>Why</dt><dd>It's the one link James sends, and the only channel with clean numbers.</dd><dt>Measure</dt><dd>Bounce rate, time on page, bookings</dd></dl>\n      <a class=\"jump\" href=\"#c-web-home\">See content</a></div>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">Website case studies page</span><span class=\"status s-build\">Needs building</span></div>\n      <dl><dt>Job</dt><dd>Make the proof checkable without naming confidential clients.</dd><dt>Why</dt><dd>Anonymous numbers weaken the Authority gate unless there's more detail one click away.</dd><dt>Measure</dt><dd>Visits from the home page</dd></dl>\n      <a class=\"jump\" href=\"#c-web-cases\">See content</a></div>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">Website about page</span><span class=\"status s-build\">Needs building</span></div>\n      <dl><dt>Job</dt><dd>Introduce Andrew and Tim, and who does what.</dd><dt>Why</dt><dd>Buyers want to know who will build the system and who they'll hear from.</dd><dt>Measure</dt><dd>Visits before booking</dd></dl>\n      <a class=\"jump\" href=\"#c-web-about\">See content</a></div>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">Website publishing page</span><span class=\"status s-fill\">Add your details</span></div>\n      <dl><dt>Job</dt><dd>Serve Brad's publishing intros with the two real Publishing System offers and proof from their own industry.</dd><dt>Why</dt><dd>Agency proof doesn't pass the Tribe gate for publishers, and Ned Clements at Whitaker House is a live, waiting lead.</dd><dt>Measure</dt><dd>Publishing bookings</dd></dl>\n      <a class=\"jump\" href=\"#c-web-publishing\">See content</a></div>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">Warrior Notes email and landing page</span><span class=\"status s-fill\">Add your details</span></div>\n      <dl><dt>Job</dt><dd>Close the first publishing pilot.</dd><dt>Why</dt><dd>The current email cites PayPal, the retail client and YouTube. The retail client has to come out, and faith-publishing proof has to go in.</dd><dt>Measure</dt><dd>Reply and a booked call</dd></dl>\n      <a class=\"jump\" href=\"#c-warrior\">See content</a></div>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">Email signatures</span><span class=\"status s-fill\">Add your details</span></div>\n      <dl><dt>Job</dt><dd>Repeat the tagline and booking link on every email.</dd><dt>Why</dt><dd>It costs nothing and appears in every conversation.</dd><dt>Measure</dt><dd>Signature link clicks</dd></dl>\n      <a class=\"jump\" href=\"#c-signature\">See content</a></div>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">LinkedIn company page</span><span class=\"status s-later\">Later</span></div>\n      <dl><dt>Job</dt><dd>Give ClearMark a home that Tim and future clients can link to.</dd><dt>Why</dt><dd>It lends credibility, but your personal profile does the real work.</dd><dt>Measure</dt><dd>Followers</dd></dl>\n      <a class=\"jump\" href=\"#c-li-company\">See content</a></div>\n  </div>\n\n  <div class=\"group\">\n    <h3>Direct outreach</h3>\n    <p>Your own network, used lightly and honestly.</p>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">Gate 1 test with three contacts</span><span class=\"status s-ready\">Ready</span></div>\n      <dl><dt>Job</dt><dd>Confirm with real buyers that the headline works.</dd><dt>Why</dt><dd>The filter's rule: don't fix lower gates until Gate 1 passes.</dd><dt>Measure</dt><dd>Whether they can say what you do after five seconds</dd></dl>\n      <a class=\"jump\" href=\"#c-gate1test\">See content</a></div>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">LinkedIn messages to your network</span><span class=\"status s-ready\">Ready</span></div>\n      <dl><dt>Job</dt><dd>Reconnect with agency contacts without pitching them.</dd><dt>Why</dt><dd>Asking for honest feedback opens more doors than a pitch does.</dd><dt>Measure</dt><dd>Replies and conversations</dd></dl>\n      <a class=\"jump\" href=\"#c-dm\">See content</a></div>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">Team announcement to warm leads</span><span class=\"status s-ready\">Ready</span></div>\n      <dl><dt>Job</dt><dd>Introduce Tim as Client Partner to your warm leads, and ask for intros.</dd><dt>Why</dt><dd>It's due by September 30, and it's a natural reason to get back in touch.</dd><dt>Measure</dt><dd>Replies and introductions</dd></dl>\n      <a class=\"jump\" href=\"#c-team\">See content</a></div>\n  </div>\n\n  <div class=\"group\">\n    <h3>Video</h3>\n    <p>Motion in a category full of still dashboards helps you stop the scroll.</p>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">Website hero loop</span><span class=\"status s-build\">Needs building</span></div>\n      <dl><dt>Job</dt><dd>Show the problem and the fix in three seconds, without words.</dd><dt>Why</dt><dd>It gives the Focus gate an unexpected opening.</dd><dt>Measure</dt><dd>Bounce rate</dd></dl>\n      <a class=\"jump\" href=\"#c-hero\">See content</a></div>\n    <div class=\"chan\"><div class=\"chan-top\"><span class=\"chan-name\">Two-minute explainer</span><span class=\"status s-later\">Later</span></div>\n      <dl><dt>Job</dt><dd>Walk a prospect through the pilot on their own time.</dd><dt>Why</dt><dd>Useful once your first case study exists.</dd><dt>Measure</dt><dd>Completion rate</dd></dl>\n      <a class=\"jump\" href=\"#c-explainer\">See content</a></div>\n  </div>\n\n  <div class=\"group\">\n    <h3>Parked for now</h3>\n    <p>Not wrong, just not now. Each has a trigger for coming back to it.</p>\n    <ul class=\"parked\">\n      <li><strong>Newsletter:</strong> revisit once you have two case studies and people are asking for more.</li>\n      <li><strong>Speaking and events:</strong> revisit after the first agency pilot gives you a story to tell on stage.</li>\n      <li><strong>Podcasts:</strong> revisit alongside speaking.</li>\n      <li><strong>Paid ads:</strong> revisit once the website converts warm traffic reliably.</li>\n      <li><strong>Instagram:</strong> agency owners don't buy there. Revisit if you open the publishing or faith market.</li>\n    </ul>\n  </div>\n</section>\n\n<section class=\"part\" id=\"content\" aria-labelledby=\"ct-h\">\n  <h2 id=\"ct-h\">Content, ready to paste</h2>\n  <p class=\"lede\">Tap a channel to open it, then tap Copy on any block. Swap out everything in <span class=\"fill\">highlighted brackets</span> before you send.</p>\n\n  <div class=\"rules\">\n    <h3>Before you paste</h3>\n    <ul>\n      <li>PayPal is cleared to name. The date is 2024; the figures are 300+ creatives and 17% to 54%.</li>\n      <li>Never name the retail client or the agency behind it in writing. Say \"a client's retail advertising program.\"</li>\n      <li>Refer to Nori as \"a Christian publishing house.\"</li>\n      <li>Never share rates or anchor-client contract terms.</li>\n      <li>Never say \"never been done before,\" \"we leave,\" or \"AI avatars.\"</li>\n      <li>Use \"we\" for ClearMark and \"I\" for your career stories.</li>\n      <li>Tim's title is Client Partner. Don't name Tim's past or current clients.</li>\n      <li>Tim never approaches your agency clients' clients.</li>\n      <li>Anything about scope, dates or price is Andrew's decision. Tim logs it and brings it to Andrew.</li>\n      <li>La Palabra was delivered by Andrew and Ilse. Don't imply the current team produces that volume in-house.</li>\n      <li>Pitch Agency Systems as \"free up your design director for sales support,\" not \"replace your design director.\" The second version is loose talk, not the agreed line.</li>\n      <li>Agency Systems setup ($2,500 to $5,000) and retainer ($500 to $1,500 a month) prices are estimates from the 7EOS product database, not numbers quoted live. Validate before quoting.</li>\n    </ul>\n  </div>\n\n  <h3 class=\"subhead\">Referral and partners</h3>\n\n  <details class=\"channel\" id=\"c-james-pitch\"><summary><span class=\"t\">James: spoken pitch</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <p class=\"use\">Send this to James so he can repeat it word for word. The last line is what prompts him to think of someone.</p>\n    <div class=\"block\"><div class=\"block-head\"><h4>Pitch</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">ClearMark fixes one problem in agencies of 15 to 200 people: everything runs through one person. Andrew is a creative director who builds AI production systems for agencies. Everyone sees the work, nothing depends on one person, and account teams sell more ideas because clients can see how it all fits.\n\nAt PayPal, he put 300+ creatives on one journey board, and email click-through went from 17% to 54%. For a client's retail advertising program, he rebuilt 500+ ads into a live system in under three months.\n\nThey build one pilot at a time.\n\nWho do you know whose best producer is drowning?</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Quote for James to approve</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">\"Most people selling AI to agencies have never run production. Andrew has. He builds the system first, and that's why the AI actually works.\"\nJames Kinney, Chief AI Officer, INVNT</div></div>\n  </div></details>\n\n  <details class=\"channel\" id=\"c-james-email\"><summary><span class=\"t\">James: forwardable intro email</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <p class=\"use\">James pastes this into an email that copies both of you.</p>\n    <div class=\"block\"><div class=\"block-head\"><h4>Email</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Subject: Intro: Andrew Kreick (ClearMark) and <span class=\"fill\">[Name]</span>\n\n<span class=\"fill\">[Name]</span>, meet Andrew Kreick. Andrew, meet <span class=\"fill\">[Name]</span>, <span class=\"fill\">[role]</span> at <span class=\"fill\">[agency]</span>.\n\nAndrew is a creative director who builds AI production systems for agencies. At PayPal, he put 300+ creatives on one journey board, and email click-through went from 17% to 54%.\n\n<span class=\"fill\">[Name]</span>, if <span class=\"fill\">[agency]</span> runs on one key person, or you've promised a client AI that isn't fully built yet, Andrew is worth 20 minutes.\n\nI'll let you two take it from here.\nJames</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Short version for LinkedIn or Slack</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\"><span class=\"fill\">[Name]</span>, you should meet Andrew Kreick. He's a creative director who builds AI production systems for agencies, so the work doesn't all run through one person. Worth 20 minutes.</div></div>\n  </div></details>\n\n  <details class=\"channel\" id=\"c-omnitas\"><summary><span class=\"t\">Omnitas referral brief</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <p class=\"use\">A one-page brief for Kuren Rai and Thomas Karlsson. Send it once your first agency pilot is signed.</p>\n    <div class=\"block\"><div class=\"block-head\"><h4>Brief</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">ClearMark and Omnitas: how we work together\n\nWho we refer\nAgencies of 15 to 200 people that run on one key person, or that have promised clients AI and automation they haven't built yet.\n\nWhat ClearMark does\nWe design the production system, build a working prototype in three weeks, run one live cycle, and train the team to run it.\n\nWhat Omnitas does\nWhen the system needs Monday.com at scale, Omnitas implements, configures and supports it.\n\nHow a referral works\n1. ClearMark qualifies the agency and runs the pilot.\n2. When the agency is ready to scale on Monday.com, we introduce Omnitas.\n3. Omnitas leads the implementation; ClearMark stays on system design.\n4. Omnitas refers North American agency and creative clients who need production system design to ClearMark.\n5. Revenue share: <span class=\"fill\">[agreed terms]</span>\n\nProof to share\nPayPal (2024): 300+ creatives on one journey board; email click-through from 17% to 54%.\nPublishing: launches cut from 360 days to 16 weeks, all four beta titles on time.\n\nContacts\nClearMark: Andrew Kreick, andrew@clearmark.bz\nOmnitas: <span class=\"fill\">[contact name and email]</span></div></div>\n  </div></details>\n\n  <details class=\"channel\" id=\"c-brad\"><summary><span class=\"t\">Brad Herman: publishing intros</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <p class=\"use\">A thank-you note with a short version Brad can forward.</p>\n    <div class=\"block\"><div class=\"block-head\"><h4>Note</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Brad, thank you again for the Warrior Notes and Whitaker House introductions. If other publishers come to mind, here's a short version you can forward:\n\n\"Andrew Kreick's team at ClearMark helps publishers stop depending on one person to keep launches on track. At a Christian publishing house, they cut launches from 360 days to 16 weeks, with all four beta titles on time.\"\n\nThank you for opening these doors.\nAndrew</div></div>\n  </div></details>\n\n  <h3 class=\"subhead\">Sales conversation</h3>\n\n  <details class=\"channel\" id=\"c-followup\"><summary><span class=\"t\">Follow-up email after an intro</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <p class=\"use\">Reply within a day, and keep it short.</p>\n    <div class=\"block\"><div class=\"block-head\"><h4>Email</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Thanks, James. Moving you to bcc.\n\n<span class=\"fill\">[Name]</span>, good to meet you. James mentioned <span class=\"fill\">[one specific detail from the intro]</span>.\n\nThe short version of what we do: we make agency production visible, so it doesn't depend on one person and clients can see how the work fits together.\n\nWould a 20-minute call next week work? You can pick a time here: <span class=\"fill\">[booking link]</span>. Or reply with two times that suit you.\n\nAndrew</div></div>\n  </div></details>\n\n  <details class=\"channel\" id=\"c-discovery\"><summary><span class=\"t\">Discovery call guide</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <p class=\"use\">About 20 minutes, with Andrew and Tim. This is the closed-door meeting, the one place you can tell the retail story in full, names included. Never put those names in writing afterward.</p>\n    <div class=\"block\"><div class=\"block-head\"><h4>Opening (2 minutes)</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Thanks for making time. This is Tim Ferman, our Client Partner; if we work together, he'll be your day-to-day contact. James said <span class=\"fill\">[detail]</span>. I'd love to hear how work moves through your agency today, and then I'll share what we've done in similar situations. If it's not a fit, I'll say so.</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Their situation (10 minutes)</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">1. Walk me through how a job moves from brief to delivery today.\n2. Who's the person everything runs through? What happens when they're out?\n3. What have you promised clients about AI or automation? How much of it is built?\n4. How do clients see the work today? What happens in reviews?\n5. Which tools does the team use: Figma, Monday.com, Adobe, others?\n6. Who would push back on a new system?\n7. If this works, what's different in 90 days?\n8. What's your timing, and who else needs to say yes?\n\nTim's questions:\n9. How do you track results for your clients today?\n10. Where does the customer journey lose people?\n11. Who runs media for your clients: your team, or another agency?</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Your story (3 minutes)</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Pick the story that matches their answers:\nOne person: the publishing story (300 tasks became 63 outcomes; launches from 360 days to 16 weeks).\nAI promise: the full retail system story, names included, spoken only.\nClient visibility: the PayPal journey board (17% to 54%).</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Close (5 minutes)</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Based on what you've said, here's what a pilot could look like: a working prototype of <span class=\"fill\">[system]</span> in your tools in three weeks, then one live <span class=\"fill\">[campaign, release or cycle]</span> to prove it. Your team runs it after that.\n\nI'd want <span class=\"fill\">[the person everything runs through]</span> involved from week one, because they know how the work really moves.\n\nWhile I build, Tim keeps you updated twice a week, and the live cycle ends with a measured result.\n\nWe build one pilot at a time. If this sounds right, I'll send a short proposal by <span class=\"fill\">[date]</span>.</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Not a fit if</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">They have neither a one-person problem nor an AI promise to keep.\nThey want ongoing staff on a retainer rather than a system.\nThey only want AI-made assets, which is the commodity we don't sell.</div></div>\n  </div></details>\n\n  <details class=\"channel\" id=\"c-proposal\"><summary><span class=\"t\">Pilot proposal template</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <p class=\"use\">Before you set the price, run the rate card rule: aim for at least 2x the floor, and rescope if the price comes in under 1.5x. The price has to cover both Andrew and Tim. The weekly plan below is a suggested structure; adjust it for each pilot.</p>\n    <div class=\"block\"><div class=\"block-head\"><h4>Proposal</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\"><span class=\"fill\">[Agency]</span> pilot proposal\nPrepared for <span class=\"fill\">[Name]</span>, <span class=\"fill\">[date]</span>\n\nWhere you are now\n<span class=\"fill\">[Their situation, in their own words from the call]</span>\n\nWhat we'll build\nA working prototype of <span class=\"fill\">[system]</span>, built in <span class=\"fill\">[your tools]</span>, in three weeks.\n\nProving it live\nWe run one real <span class=\"fill\">[campaign, release or cycle]</span> on the prototype, so you see it working before you commit further. It ends with a results summary showing what we measured.\n\nWhat your team gets\nA shared view of the work, training for the people who'll run it, and documentation so it keeps working after we step back.\n\nWho's involved\nFrom ClearMark: Andrew Kreick builds the system. Tim Ferman, Client Partner, is your day-to-day contact.\nFrom <span class=\"fill\">[agency]</span>: <span class=\"fill\">[names]</span>, including <span class=\"fill\">[the person everything runs through]</span>, from the first week.\n\nHow we'll keep you updated\nTim sends an update every <span class=\"fill\">[two days, e.g. Tuesday and Friday]</span>: what's done, what's next, and any question for you.\nEach week, a 20-minute check-in shows progress on the shared board.\nAndrew leads the kickoff, a mid-build preview, and the handover.\n\nTimeline\nWeek 1: map how work moves today and design the system.\nWeek 2: build the prototype.\nWeek 3: test it and train the team.\nThen: one live <span class=\"fill\">[cycle]</span> over <span class=\"fill\">[length]</span>.\n\nInvestment\n<span class=\"fill\">[Fixed price]</span>, <span class=\"fill\">[payment terms]</span>\n\nWhat we need from you\nAccess to <span class=\"fill\">[tools]</span>, <span class=\"fill\">[hours]</span> a week from <span class=\"fill\">[key person]</span>, and a decision-maker at each review.\n\nNext step\nSign by <span class=\"fill\">[date]</span> to hold the <span class=\"fill\">[start date]</span> slot. We build one pilot at a time.\n\nAndrew Kreick and Tim Ferman, ClearMark\nandrew@clearmark.bz</div></div>\n  </div></details>\n\n  <details class=\"channel\" id=\"c-onepager\"><summary><span class=\"t\">Case study one-pager</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <p class=\"use\">Send it after the call so the champion can forward it to the owner.</p>\n    <div class=\"block\"><div class=\"block-head\"><h4>One-pager</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">ClearMark\nYour single source of truth shouldn't be a person.\nWe build AI production systems agencies can see and run.\n\nPayPal, 2024\n300+ creatives on one journey board. With agency and client seeing the whole journey, a new email strategy became obvious, and click-through went from 17% to 54%.\n\nA client's retail advertising program\n500+ ads moved from Photoshop and After Effects into one live system in under three months. The prototype was approved, a full live month was delivered, and changes are now approved in real time.\n\nA Christian publishing house\n300 tracked tasks became 63 visible outcomes. Launches went from 360 days to 16 weeks, and all four beta titles shipped on time.\n\nLa Palabra\n480 finished posts and reels in 49 working hours, from a two-person team.\n\nHow the pilot works\nA working prototype in three weeks, then one live cycle that ends with a measured result. You'll hear from us twice a week while we build. After that, your team runs it. We build one pilot at a time.\n\nAndrew Kreick, andrew@clearmark.bz, <span class=\"fill\">[booking link]</span>\nClearMark. Make it visible.</div></div>\n  </div></details>\n\n  <details class=\"channel\" id=\"c-casestudy-request\"><summary><span class=\"t\">Case study request after a pilot</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <p class=\"use\">Tim sends this right after the results summary, while the results are fresh.</p>\n    <div class=\"block\"><div class=\"block-head\"><h4>Email</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Subject: One favor now that <span class=\"fill\">[system]</span> is live\n\n<span class=\"fill\">[Name]</span>, thank you for trusting us with <span class=\"fill\">[agency]</span>'s pilot. Now that the live cycle is done, could I ask two things?\n\n1. A sentence or two on what changed for your team, which we could quote with your name and title.\n2. One number you've noticed: faster turnaround, fewer handoffs, more ideas approved, or anything else you track.\n\nYou'll see everything before it's published, and we'll leave out anything you'd rather keep private.\n\nThank you,\nTim and Andrew</div></div>\n  </div></details>\n\n  <h3 class=\"subhead\">During the pilot</h3>\n\n  <details class=\"channel\" id=\"c-update\"><summary><span class=\"t\">Twice-weekly client update</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <p class=\"use\">Tim sends this on the same two days every week, even when the news is small.</p>\n    <div class=\"block\"><div class=\"block-head\"><h4>Email or message</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Subject: <span class=\"fill\">[Agency]</span> pilot, update <span class=\"fill\">[number]</span>\n\nHi <span class=\"fill\">[Name]</span>,\n\nQuick update on the pilot.\n\nDone since last time: <span class=\"fill\">[one to three items]</span>\nNext up: <span class=\"fill\">[one to three items]</span>\nOne question for you: <span class=\"fill\">[question, or \"none this time\"]</span>\nOn track for: <span class=\"fill\">[milestone]</span> on <span class=\"fill\">[date]</span>\n\nTim</div></div>\n  </div></details>\n\n  <details class=\"channel\" id=\"c-checkin\"><summary><span class=\"t\">Weekly check-in agenda</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <p class=\"use\">20 minutes, led by Tim. Andrew joins for kickoff, the mid-build preview and the handover.</p>\n    <div class=\"block\"><div class=\"block-head\"><h4>Agenda</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">1. What's built, shown on the shared board (5 minutes)\n2. What's next this week (5 minutes)\n3. Open questions and decisions (5 minutes)\n4. What we'll measure in the live cycle (5 minutes)\n\nBefore closing: confirm the next two update days and any access we still need.</div></div>\n  </div></details>\n\n  <details class=\"channel\" id=\"c-log\"><summary><span class=\"t\">Question log and daily sync</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <p class=\"use\">Tim answers questions about status and process. Scope, dates and price always go to Andrew.</p>\n    <div class=\"block\"><div class=\"block-head\"><h4>Question log columns</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Date | Question | Asked by | Answer | Answered by | Changes scope? (if yes, Andrew decides)</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Daily sync message (Andrew to Tim)</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Built today: <span class=\"fill\">[items]</span>\nStuck on: <span class=\"fill\">[item, or nothing]</span>\nWorth telling the client: <span class=\"fill\">[item, or nothing]</span>\nAnswers to their questions: <span class=\"fill\">[answers]</span></div></div>\n  </div></details>\n\n  <details class=\"channel\" id=\"c-results\"><summary><span class=\"t\">Live-cycle results summary</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <p class=\"use\">Tim sends this at the end of the live cycle. Use only numbers the client can see for themselves.</p>\n    <div class=\"block\"><div class=\"block-head\"><h4>Summary</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Subject: <span class=\"fill\">[Agency]</span> pilot results\n\nWhat we built: <span class=\"fill\">[system, in one sentence]</span>\nWhat ran: <span class=\"fill\">[the live campaign, release or cycle]</span>\nWhat we measured: <span class=\"fill\">[metrics]</span>\nResults: <span class=\"fill\">[metric]</span> went from <span class=\"fill\">[before]</span> to <span class=\"fill\">[after]</span>\nWhat we learned: <span class=\"fill\">[one or two points]</span>\nFrom here: your team runs the system. Training is done, and the documentation is <span class=\"fill\">[link]</span>.\nNext options: <span class=\"fill\">[extend to more workflows, or ongoing support]</span>\n\nTim and Andrew</div></div>\n  </div></details>\n\n  <h3 class=\"subhead\">Owned channels</h3>\n\n  <details class=\"channel\" id=\"c-linkedin-profile\"><summary><span class=\"t\">LinkedIn profile and banner</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <div class=\"block\"><div class=\"block-head\"><h4>Headline</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Creative director building AI production systems for agencies | Founder, ClearMark</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Banner text</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Your single source of truth shouldn't be a person.\nClearMark. Make it visible.</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>About</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Most agencies have the same hidden risk: one person who knows where every job stands. When they're out, production stalls. When they burn out, the agency feels it.\n\nI've spent 26 years in agency creative and production, and served as one of the Government of Canada's first creative directors. At PayPal, I put 300+ creatives on one journey board so agency and client could see the whole journey, and email click-through went from 17% to 54%.\n\nToday I run ClearMark with Tim Ferman, our Client Partner. We build AI production systems agencies can see and run:\n→ A shared view of the work, so ideas sell faster\n→ Systems in the tools you already use\n→ Your team trained to run it without us\n\nWe build one pilot at a time. If your best producer is drowning, message me.</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Experience and Featured notes</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Experience: list your former agency employer with no client names. PayPal can be described with its result.\nFeatured: website link, case studies page, and one pinned post (Thursday's board post is a good choice).</div></div>\n  </div></details>\n\n  <details class=\"channel\" id=\"c-tim-linkedin\"><summary><span class=\"t\">Tim's LinkedIn profile</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <p class=\"use\">Tim adds this as a new experience entry. His Perfect Storm role can stay as it is.</p>\n    <div class=\"block\"><div class=\"block-head\"><h4>Experience entry</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Client Partner, ClearMark\n\nI'm the day-to-day contact for ClearMark's agency pilots. While Andrew builds the production system, I keep clients updated twice a week, answer their questions, and make sure every live cycle ends with a measured result.</div></div>\n  </div></details>\n\n  <details class=\"channel\" id=\"c-posts\"><summary><span class=\"t\">LinkedIn posts: first week</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <p class=\"use\">One post per weekday theme. Batch the week in one sitting, and keep visuals simple. Only Friday asks for a pilot call.</p>\n    <div class=\"block\"><div class=\"block-head\"><h4>Monday: one-person syndrome</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Every agency I've worked in had a Sarah.\n\nDifferent name each time. Same job: she knew where every project stood.\n\nClients called her. Producers checked with her. Creative directors asked her before they checked the brief.\n\nWhen Sarah took a week off, nothing broke. It just stopped.\n\nThat's not a Sarah problem. She's the most reliable person in the building. It's a system problem: the agency's single source of truth is a person.\n\nThe fix isn't another tool. It's making the work visible, so everyone can see what Sarah sees.\n\nWho's the Sarah at your agency?\n\nClearMark. Make it visible.</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Tuesday: contrarian take</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Stop tracking tasks.\n\nAt a Christian publishing house, the production board had 300 tasks on it. Everyone updated it. Nobody could read it.\n\nWe replaced those 300 tasks with 63 outcomes. Each one had a clear start, a clear finish and a date. Each team kept its own way of working.\n\nLaunches went from 360 days to 16 weeks. All four beta titles shipped on time.\n\nTasks tell you who's busy. Outcomes tell you what's done.\n\nWhat's on your board right now?</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Wednesday: show the work</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Twelve text styles. One session.\n\nThis is a full typography system, built and applied in Figma through its API rather than by hand. Every heading, body style and caption is set once and applied everywhere.\n\nFor an agency, that's the difference between fixing type file by file and changing it once, everywhere.\n\nSystem first. Then AI.\n\n<span class=\"fill\">[Attach the screen recording]</span></div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Thursday: lessons from 26 years</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">The best sales tool I ever built for an agency wasn't a deck.\n\nIt was a board.\n\nAt PayPal, we put 300+ pieces of performance creative on one board, from acquisition to fulfillment to retention. Agency and client teams could see the whole journey at once, or zoom into any single piece.\n\nTwo things happened.\n\nFirst, the account team started selling ideas in the room. When the client can see how everything fits, a new idea doesn't need a deck. It needs a spot on the board.\n\nSecond, a strategy nobody could see before became obvious. We rebuilt the email sequence around it, and click-through went from 17% to 54%.\n\nVisibility isn't admin. It's how work gets sold.</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Friday: offer and proof</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Your agency sold the client on AI.\nWho's building the system?\n\nA client had just been sold on automated creative. The system didn't exist yet. I had under three months.\n\nWe rebuilt 500+ ads from Photoshop and After Effects into one live system. First a prototype, then a full live month to prove it. Now changes happen in one shared file while the account team and client watch and approve.\n\nIf your agency is in that spot, we build one pilot at a time: a working prototype in three weeks, one live cycle, then your team runs it. You'll hear from us twice a week while we build.\n\nNext opening: <span class=\"fill\">[date]</span>. Message me.</div></div>\n  </div></details>\n\n  <details class=\"channel\" id=\"c-web-home\"><summary><span class=\"t\">Website home page</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <p class=\"use\">Build the sections in this order. Each one does the job of one gate.</p>\n    <div class=\"block\"><div class=\"block-head\"><h4>Gate 1: headline</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Your single source of truth shouldn't be a person.\nMake it visible.</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Gate 2: subhead and proof strip</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">When every job runs through your best creative, the agency stalls when they do. We build AI production systems your team can run, and a shared view of the work that makes your next idea easier to sell, from a creative director with 26 years inside agencies.\n\nPayPal: 300+ creatives on one journey board, email click-through from 17% to 54%\n500+ retail ads rebuilt as a live system in under three months\nLa Palabra: 480 finished assets in 49 hours</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Gate 3: sound familiar?</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">You sold the client on AI. Now someone has to build it.\nA client had just moved its retail advertising to be automated at scale. Every ad lived in Photoshop and After Effects, and I had under three months. We rebuilt 500+ ads as one live system with the ops and account teams, got the prototype approved, then delivered a full live month.\n\nBefore, every change went from the designer with the file, to a specialist who reopened it, to a deck for the client. After, changes happened in one shared file, in real time, while the account team and client watched and approved.\n\nEvery job runs through one producer.\nWhen they're out, production waits. When they burn out, the agency feels it.\n\nYour client can't see how the work fits together.\nIn 2024, for PayPal, we put 300+ pieces of creative on one board, from acquisition to retention. With agency and client looking at the same view, a new email strategy became obvious, and click-through went from 17% to 54%.\n\n<span class=\"fill\">[James Kinney quote, once approved]</span></div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Gate 4: pilot and call to action</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Your client is already waiting to see the automation you promised. And every review where they can't see how the work fits is an idea you don't sell.\n\nHow the pilot works\nA working prototype in your tools in three weeks. Then one live cycle to prove it, ending with a measured result. After that, your team runs it.\n\nYou'll hear from us twice a week while we build.\n\nWe build one pilot at a time. Next opening: <span class=\"fill\">[date]</span>.\n\n[Scope a pilot]\n\nSome of our best work we can only walk you through in person. That's how agency work should be protected.\n\nClearMark. Make it visible.</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Page title and search description</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Title: Agency workflow systems | ClearMark\nDescription: Workflow systems for agencies that run on one person. A creative director builds your AI production system in three weeks, and your team runs it.</div></div>\n  </div></details>\n\n  <details class=\"channel\" id=\"c-web-cases\"><summary><span class=\"t\">Website case studies page</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <p class=\"use\">Show a mock journey board with invented creative. Never use real PayPal assets.</p>\n    <div class=\"block\"><div class=\"block-head\"><h4>Intro</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">The work, made visible\nFour systems, four results. Some clients we can name; some we can only walk you through in person.</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>PayPal</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">PayPal: one board for the whole journey (2024)\nThe problem: 300+ pieces of performance creative, spread across acquisition, fulfillment and retention, with no single view for agency or client.\nWhat we built: one board holding every piece, with a top-line view of the whole journey and the detail of any single piece.\nWhat changed: agency and client reviewed the work together, and the account team sold ideas in the room.\nThe result: a new email strategy became visible, and click-through went from 17% to 54%.</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Retail advertising program</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">A retail advertising program: the AI that was promised, actually built\nThe situation: a client had just moved its retail advertising to be automated at scale. The system didn't exist yet, and there were under three months to build it.\nWhat we built: 500+ TV and digital ads moved from Photoshop and After Effects into one live system, with the ops and account teams.\nWhat changed: instead of a designer, a specialist and a presentation deck, changes happen in one shared file, approved in real time by the account team and client.\nThe result: the prototype was approved, and a full live month was delivered. <span class=\"fill\">[Before-and-after turnaround, if available]</span></div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Publishing house</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">A Christian publishing house: launches in 16 weeks\nThe problem: 300 tracked tasks, and nobody could tell what was done.\nWhat we built: 63 visible outcomes, each with a clear start, finish and date, while every department kept its own methods.\nThe result: launches went from 360 days to 16 weeks, and all four beta titles shipped on time.</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>La Palabra</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">La Palabra: a 30-day campaign from two people\nWhat we built: a custom design system of 120+ images, automation, and a campaign across social, PDF and print.\nThe result: 240 posts, 240 reels, a 50-page PDF and a 32-page print devotional, in 49 working hours, delivered to an audience of 10,000+ followers.</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Closing</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Some of our best work we can only walk you through in person. That's how agency work should be protected.\n[Scope a pilot]</div></div>\n  </div></details>\n\n  <details class=\"channel\" id=\"c-web-about\"><summary><span class=\"t\">Website about page</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <div class=\"block\"><div class=\"block-head\"><h4>About</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">About ClearMark\nClearMark builds AI production systems for agencies. We're a team of two, and we build one pilot at a time.\n\nAndrew Kreick, founder\nAndrew is a creative director with 26 years inside agencies. He has built production systems for brands including PayPal, served as one of the Government of Canada's first creative directors, and created the SURGE method that took a publisher's launches from 360 days to 16 weeks.\n\nTim Ferman, Client Partner\nTim is your day-to-day contact while Andrew builds. He founded Perfect Storm Digital, started as a late-'90s webmaster, and has spent more than 25 years in digital marketing, with clients who have stayed for over a decade. At ClearMark, he keeps you updated twice a week, answers your questions, and makes sure every pilot's live cycle ends with a measured result.\n\nHow we work\nWe build the system first, then add AI.\nYour teams keep their own ways of working; we make the work visible across them.\nThe people the work runs through help design the system.\nWe keep you updated twice a week while we build.\nWe train your team to run it without us.\nWe keep client work confidential.</div></div>\n  </div></details>\n\n  <details class=\"channel\" id=\"c-web-publishing\"><summary><span class=\"t\">Website publishing page</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <div class=\"block\"><div class=\"block-head\"><h4>Page</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Your launches shouldn't depend on one person.\n\nAt a Christian publishing house, we replaced 300 tracked tasks with 63 visible outcomes, and launches went from 360 days to 16 weeks, with all four beta titles on time.\n\nWe also produced La Palabra's 30-day devotional campaign: 480 finished posts and reels, a 50-page PDF and a 32-page print devotional, in 49 working hours.\n\nTwo ways to work together:\n\nBook Relaunch Calendar — a 30-day content calendar and relaunch campaign that resurfaces a dormant title, built on the same method behind La Palabra.\n\nConcept-to-Market Sprint — a raw concept or manuscript turned into a full go-to-market pitch plus sample content, in days, not months.\n\n[Scope a project]</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Before you publish this page</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Confirm pricing before it goes live: <span class=\"fill\">[$1,500 to $3,000 for the Relaunch Calendar, $2,500 to $5,000 for the Concept-to-Market Sprint]</span> are estimates from the 7EOS product database, modeled on delivery times already proven for Nori and La Palabra, not numbers quoted to a publisher yet.</div></div>\n  </div></details>\n\n  <details class=\"channel\" id=\"c-warrior\"><summary><span class=\"t\">Warrior Notes fixes</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <p class=\"use\">Swap this paragraph in for the PayPal, retail client and YouTube proof in the Victory Jet email and landing page.</p>\n    <div class=\"block\"><div class=\"block-head\"><h4>Replacement proof paragraph</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">We've done this in publishing before. At a Christian publishing house, we replaced 300 tracked tasks with 63 visible outcomes, and launches went from 360 days to 16 weeks, with all four beta titles on time. We also produced La Palabra's 30-day devotional campaign: 480 finished posts and reels, a 50-page PDF and a 32-page print devotional, in 49 working hours.</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Before you send</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Remove every reference to the retail client.\nReprice or rescope so the deal passes the rate card rule.\nReplace the placeholder YouTube and Calendly links.\nReplace the lorem ipsum copy on the landing page.\nUse \"your team runs it,\" not \"we leave.\"</div></div>\n  </div></details>\n\n  <details class=\"channel\" id=\"c-signature\"><summary><span class=\"t\">Email signatures</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <div class=\"block\"><div class=\"block-head\"><h4>Signature</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Andrew Kreick\nFounder, ClearMark\nCreative director building AI production systems for agencies\nandrew@clearmark.bz\nclearmark.bz\n<span class=\"fill\">[Booking link]</span>\n\nClearMark. Make it visible.</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Tim's signature</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Tim Ferman\nClient Partner, ClearMark\n<span class=\"fill\">[Tim's ClearMark email]</span>\nclearmark.bz\n\nClearMark. Make it visible.</div></div>\n  </div></details>\n\n  <details class=\"channel\" id=\"c-li-company\"><summary><span class=\"t\">LinkedIn company page</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <div class=\"block\"><div class=\"block-head\"><h4>Tagline</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">AI production systems for agencies that run on one person. Make it visible.</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Overview</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">ClearMark builds AI production systems for agencies of 15 to 200 people. We make production visible, so the work doesn't depend on one person, and we give agency and client a shared view that makes ideas easier to sell.\n\nFounded by creative director Andrew Kreick, who has spent 26 years inside agencies.\n\nWe build one pilot at a time: a working prototype in three weeks, one live cycle, then your team runs it.</div></div>\n  </div></details>\n\n  <h3 class=\"subhead\">Direct outreach</h3>\n\n  <details class=\"channel\" id=\"c-gate1test\"><summary><span class=\"t\">Gate 1 test with three contacts</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <p class=\"use\">Test with three agency owners or production leads before building the website.</p>\n    <div class=\"block\"><div class=\"block-head\"><h4>Test script</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">1. Show only the headline and tagline for five seconds, then hide them.\n2. Ask: What does this company do?\n3. Ask: Would you keep reading? Why or why not?\n4. Ask: What does \"Make it visible\" mean to you?\n\nIt passes if they describe making work visible or not depending on one person, and say they'd keep reading.</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Discovery questions (if they're open to it)</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Is there one person your agency runs through? What happens when they're out?\nHave you promised a client AI or automation that isn't fully built yet?\nWhat would it be worth to fix either one?\nWho would need to say yes?</div></div>\n  </div></details>\n\n  <details class=\"channel\" id=\"c-dm\"><summary><span class=\"t\">LinkedIn message to your network</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <p class=\"use\">Send once your profile is live. It doubles as the invitation for the Gate 1 test.</p>\n    <div class=\"block\"><div class=\"block-head\"><h4>Message</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Hi <span class=\"fill\">[Name]</span>, hope you're well. I've started ClearMark with Tim Ferman. We build AI production systems for agencies, so the work doesn't all run through one person.\n\nI'm not pitching you. I'm testing our website headline and would value five minutes of your honest reaction. Would you be open to a quick call or a few messages this week?</div></div>\n  </div></details>\n\n  <details class=\"channel\" id=\"c-team\"><summary><span class=\"t\">Team announcement to warm leads</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <p class=\"use\">Due by September 30. Send to Omnitas and James. For Brad and Warrior Notes, use the publishing version.</p>\n    <div class=\"block\"><div class=\"block-head\"><h4>Agency version</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Subject: Meet ClearMark's Client Partner\n\n<span class=\"fill\">[Name]</span>, a quick update. Tim Ferman has joined ClearMark as Client Partner.\n\nTim founded Perfect Storm Digital and has spent more than 25 years in digital marketing. While I build, Tim is the client's day-to-day contact: they hear from him twice a week, and he makes sure every pilot's live cycle ends with a measured result.\n\nWe're focusing on agencies of 15 to 200 people that run on one person, or that have promised clients AI they haven't built yet. If someone comes to mind, I'd be grateful for an intro.\n\nAndrew</div></div>\n    <div class=\"block\"><div class=\"block-head\"><h4>Publishing version (swap in for the focus paragraph)</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">We're helping publishers whose launches depend on one person. At a Christian publishing house, we cut launches from 360 days to 16 weeks, with all four beta titles on time.</div></div>\n  </div></details>\n\n  <h3 class=\"subhead\">Video</h3>\n\n  <details class=\"channel\" id=\"c-hero\"><summary><span class=\"t\">Website hero loop</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <p class=\"use\">A storyboard for whoever builds it. Keep it simple, silent, and under four seconds.</p>\n    <div class=\"block\"><div class=\"block-head\"><h4>Storyboard</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">Frame 1 (0 to 1.2 seconds): a simple workflow diagram. Every line runs through one node marked with a person icon.\nFrame 2 (1.2 to 2.2 seconds): that node dims, and the lines stop moving.\nFrame 3 (2.2 to 3.5 seconds): the lines reroute into one shared board and start moving again. \"Make it visible.\" appears.\n\nSpecs: brand colors, no text other than the tagline, lightweight SVG or Lottie. If a visitor has reduced motion turned on, show the final frame as a still image.\n\nParked: the headline animation that swaps \"truth\" and \"failure.\"</div></div>\n  </div></details>\n\n  <details class=\"channel\" id=\"c-explainer\"><summary><span class=\"t\">Two-minute explainer (later)</span><span class=\"chev\" aria-hidden=\"true\"></span></summary><div class=\"channel-body\">\n    <div class=\"block\"><div class=\"block-head\"><h4>Outline</h4><button class=\"copy\" type=\"button\">Copy</button></div><div class=\"copytext\">0:00 to 0:15: \"Your agency sold the client on AI. Who's building the system?\"\n0:15 to 0:45: The problem. One person holds the work, and the client can't see how it fits.\n0:45 to 1:20: The proof. The PayPal journey board, and the retail system (unnamed).\n1:20 to 1:45: The pilot. A prototype in three weeks, one live cycle, then your team runs it.\n1:45 to 2:00: \"We build one pilot at a time. ClearMark. Make it visible.\"</div></div>\n  </div></details>\n</section>\n\n<section class=\"part\" id=\"timeline\" aria-labelledby=\"tl-h\">\n  <h2 id=\"tl-h\">Timeline</h2>\n  <p class=\"lede\">Work through these in order. Tick items as you finish them; your checks are saved on this device only.</p>\n  <p class=\"progress\" id=\"progress\" aria-live=\"polite\"></p>\n  <ol class=\"weeks\">\n    <li class=\"week\">\n      <h3>This week</h3><p class=\"when\">September 15 to 21</p>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t1\"><span>Rewrite the LinkedIn profile and banner<span class=\"who\">Andrew</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t2\"><span>Update the email signature<span class=\"who\">Andrew</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t3\"><span>Send James the pitch, the intro email, and his quote to approve<span class=\"who\">Andrew</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t4\"><span>Message three agency contacts to set up the Gate 1 test<span class=\"who\">Andrew</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t30\"><span>Confirm Tim's role: title, fee split, non-solicit agreement, and what he can decide on his own<span class=\"who\">Andrew and Tim</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t31\"><span>Tim adds his ClearMark role to LinkedIn<span class=\"who\">Tim</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t6\"><span>Batch next week's five LinkedIn posts<span class=\"who\">Andrew</span></span></label>\n    </li>\n    <li class=\"week\">\n      <h3>Launch run-up</h3><p class=\"when\">September 22 to 30</p>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t7\"><span>Run the Gate 1 test and adjust the headline if needed<span class=\"who\">Andrew</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t8\"><span>Start daily LinkedIn posts<span class=\"who\">Andrew</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t9\"><span>Build the website home, case studies and about pages, including Tim's bio and photo<span class=\"who\">Andrew and Tim</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t10\"><span>Build the hero loop and the mock journey board<span class=\"who\">Andrew, or a freelance designer</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t11\"><span>Warrior Notes: reprice or rescope, apply the fixes, send<span class=\"who\">Andrew</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t12\"><span>Send Whitaker House outreach and Brad's note<span class=\"who\">Andrew</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t13\"><span>Send the announcement introducing Tim by September 30<span class=\"who\">Andrew</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t14\"><span>Launch clearmark.bz on September 30<span class=\"who\">Andrew and Tim</span></span></label>\n    </li>\n    <li class=\"week\">\n      <h3>October</h3><p class=\"when\">First conversations</p>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t15\"><span>Follow up on James's intros and run discovery calls together<span class=\"who\">Andrew and Tim</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t16\"><span>Finalize the pilot proposal template and case study one-pager<span class=\"who\">Andrew and Tim</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t32\"><span>Tailor the during-the-pilot templates and pick the two update days<span class=\"who\">Tim</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t17\"><span>Anchor client 2027 renewal conversation, by mid-October (internal)<span class=\"who\">Andrew</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t18\"><span>Follow up with Spector &amp; Co using the new positioning<span class=\"who\">Andrew</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t19\"><span>Set the next pilot opening date and add it to the website and Friday posts<span class=\"who\">Andrew</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t20\"><span>Set up the LinkedIn company page and the website publishing page<span class=\"who\">Tim</span></span></label>\n    </li>\n    <li class=\"week\">\n      <h3>November</h3><p class=\"when\">First agency pilot</p>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t21\"><span>Sign the first agency pilot<span class=\"who\">Andrew</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t22\"><span>Build the three-week prototype, one pilot at a time<span class=\"who\">Andrew</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t33\"><span>Lead the client: twice-weekly updates, weekly check-ins, question log<span class=\"who\">Tim</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t23\"><span>Send Omnitas the referral brief and introduce the client<span class=\"who\">Andrew</span></span></label>\n    </li>\n    <li class=\"week\">\n      <h3>December</h3><p class=\"when\">Prove it</p>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t24\"><span>Run the live cycle and train the client's team<span class=\"who\">Andrew</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t34\"><span>Measure the live cycle and send the results summary<span class=\"who\">Tim</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t25\"><span>Send the case study request<span class=\"who\">Tim</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t26\"><span>Anchor client contract ends or renews on December 31 (internal)<span class=\"who\">Andrew</span></span></label>\n    </li>\n    <li class=\"week\">\n      <h3>January 2027</h3><p class=\"when\">Build on the proof</p>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t27\"><span>Publish the first agency case study<span class=\"who\">Andrew and Tim</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t35\"><span>Review how the Andrew and Tim model worked, and whether it frees capacity<span class=\"who\">Andrew and Tim</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t28\"><span>Decide whether capacity allows two pilots at once<span class=\"who\">Andrew</span></span></label>\n      <label class=\"task\"><input type=\"checkbox\" data-key=\"t29\"><span>Review parked channels and the rate card<span class=\"who\">Andrew</span></span></label>\n    </li>\n  </ol>\n</section>\n\n</main>\n<footer class=\"wrap\">\n  <p>Source documents: P059 Brand Messaging Framework v2 and P056 Agency Pitch Library v2 in Clearmark Corporate Documents. Offer ladder and Publishing System pricing from the 7EOS product database; Content System pilot status from the 7EOS sales pipeline; positioning options cross-checked against the Tim–Andrew brainstorm transcript, September 17, 2026. Text in <span class=\"fill\">highlighted brackets</span> needs your details before use.</p>\n</footer>";
